// Full run-down of what the selected race grants (mirrors the class step's progression detail): a summary of
// mechanical grants + every racial trait with its description.
function renderRaceDetail(){
  const box = $("wiz-race-detail"); if(!box) return;
  const r = DATA && findBy(DATA.races, $("wiz-race").value);
  if(!r){ box.innerHTML = ""; return; }
  const grants = [];
  const ab = [];
  (r.ability||[]).forEach(blk => Object.entries(blk).forEach(([k,v])=>{
    if(ABKEYS.includes(k)) ab.push(ABBR[k]+" +"+v);
    else if(k==="choose") ab.push(`+${v.amount||1} to ${v.count} of your choice`);
  }));
  if(ab.length) grants.push("Ability Score Increase: " + ab.join(", "));
  grants.push("Size: " + (r.size || "Medium") + " · Speed: " + (r.speed || 30) + " ft." + (r.speedExtra ? " (" + r.speedExtra + ")" : ""));
  if(r.darkvision) grants.push("Darkvision: " + r.darkvision + " ft.");
  const p = r.prof || {};
  if(p.skills && p.skills.length) grants.push("Skill proficiencies: " + p.skills.map(_titlecase).join(", "));
  if(p.skillChoose && p.skillChoose.count) grants.push("Skill proficiencies: choose " + p.skillChoose.count + ((p.skillChoose.from && p.skillChoose.from.length) ? " (" + p.skillChoose.from.map(_titlecase).join(", ") + ")" : " from any"));
  if(p.weapons && p.weapons.length) grants.push("Weapon proficiencies: " + p.weapons.join(", "));
  if(p.armor && p.armor.length) grants.push("Armor proficiencies: " + p.armor.join(", "));
  if(p.tools && p.tools.length) grants.push("Tool proficiencies: " + p.tools.map(_titlecase).join(", "));
  if(p.languages && p.languages.length) grants.push("Languages: " + p.languages.join(", "));
