function scrollListToActive(box){   // reveal the highlighted button within its own scroll box only (never the page/modal); no-op if already visible
  const a = box && box.querySelector(".active"); if(!a) return;
  const lr = box.getBoundingClientRect(), ar = a.getBoundingClientRect();
  if(ar.top < lr.top) box.scrollTop -= (lr.top - ar.top);
  else if(ar.bottom > lr.bottom) box.scrollTop += (ar.bottom - lr.bottom);
}
