      if(removed.length){ _removeBlocks("features", removed); genTceRemoved.push(...removed); } }
    const block = `${r.label} (TCE, ${r.cls} ${r.lvl}). ${r.desc}`;
    if(!t.value.includes(block)){ t.value = t.value.trim() ? t.value + "\n\n" + block : block; genTce.push(block); }
  });
  autoGrow(t);
}
